    # dp[i][x]: number of sequences of length i ending with element x
    # next element >= 2 * previous element
    if n == 1:
        return m

    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1  # sequences of length 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # To efficiently sum dp[y] for y >= 2*x, we precompute suffix sums
        suffix_sum = [0] * (m + 2)
        for y in range(m, 0, -1):
            suffix_sum[y] = suffix_sum[y + 1] + dp[y]
        for x in range(1, m + 1):
            start = 2 * x
            if start <= m:
                new_dp[x] = suffix_sum[start]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:])

