def substract_elements(*collections):
    if not collections:
        return None

    # Determine if all inputs at this level are collections (list or tuple)
    # If so, recurse element-wise
    # Otherwise, subtract them as numbers

    # Check if all are lists or tuples
    if all(isinstance(c, (list, tuple)) for c in collections):
        # Lengths must match to do element-wise subtraction
        lengths = [len(c) for c in collections]
        if len(set(lengths)) != 1:
            raise ValueError("All collections must have the same length at each nested level")
        length = lengths[0]

        # Recurse element-wise
        result = []
        for i in range(length):
            # Extract the i-th element from each collection and recurse
            elems = [c[i] for c in collections]
            result.append(substract_elements(*elems))
        # Return same type as inputs (if all tuples, return tuple)
        if all(isinstance(c, tuple) for c in collections):
            return tuple(result)
        else:
            return result
    else:
        # Not all are collections, assume numeric values and subtract:
        # Perform subtraction as: first - second - third - ...
        # Validate all are numeric (int or float)
        for c in collections:
            if not isinstance(c, (int, float)):
                raise TypeError("All leaf elements must be int or float for subtraction")
        it = iter(collections)
        total = next(it)
        for v in it:
            total -= v
        return total

