def find_solution(a: int, b: int, n: int):
    # We want non-negative integers x, y >= 0 such that a*x + b*y = n.
    # If no such solution exists, return None.

    # Handle trivial cases
    if n < 0:
        return None
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Extended Euclidean Algorithm to find one integer solution of a*x + b*y = gcd(a,b)
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        gcd, s1, t1 = extended_gcd(y, x % y)
        s = t1
        t = s1 - (x // y) * t1
        return (gcd, s, t)

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return None

    # Scale the solution to n
    x0 *= n // gcd
    y0 *= n // gcd

    # Adjust signs according to original a,b signs
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # General solution:
    # x = x0 + k * (b/gcd)
    # y = y0 - k * (a/gcd)
    # We want x >= 0 and y >= 0.

    a_div = b // gcd
    b_div = a // gcd

    # Find k such that x >= 0:
    # x0 + k * a_div >= 0 => k >= -x0 / a_div if a_div > 0 else k <= -x0 / a_div
    # Similarly for y >= 0:
    # y0 - k * b_div >= 0 => k <= y0 / b_div if b_div > 0 else k >= y0 / b_div

    from math import ceil, floor

    if a_div == 0:  # prevent division by zero (should not happen since gcd divides b)
        return None
    if b_div == 0:  # prevent division by zero (should not happen since gcd divides a)
        return None

    # Determine bounds for k:
    if a_div > 0:
        k_min = ceil(-x0 / a_div)
    else:
        k_min = floor(-x0 / a_div)

    if b_div > 0:
        k_max = floor(y0 / b_div)
    else:
        k_max = ceil(y0 / b_div)

    # Check if there exists k with k_min <= k <= k_max
    if a_div > 0 and b_div > 0:
        if k_min > k_max:
            return None
        k = k_min  # smallest k satisfying constraints
    elif a_div > 0 and b_div < 0:
        if k_min > k_max:
            return None
        k = k_max  # for b_div < 0, k_max is lower bound, k_min upper bound
    elif a_div < 0 and b_div > 0:
        if k_max > k_min:
            return None
        k = k_min  # in this case k_min is upper bound, k_max lower bound
    else:  # a_div < 0 and b_div < 0
        if k_max > k_min:
            return None
        k = k_max

    x = x0 + k * a_div
    y = y0 - k * b_div

    if x >= 0 and y >= 0:
        return (x, y)
    return None

