    # The quotient = b! / a! = (a+1) * (a+2) * ... * b
    # We need the last digit of this product.
    # If a == b, quotient = 1, last digit = 1
    if a == b:
        return 1
    prod_last_digit = 1
    for x in range(a + 1, b + 1):
        prod_last_digit = (prod_last_digit * (x % 10)) % 10
        if prod_last_digit == 0:
            # Once we hit 0, last digit will remain 0
            break
    return prod_last_digit

