def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(n: int) -> bool:
        return all(ch == '9' for ch in str(n))

    s = str(num)
    length = len(s)

    # If all 9's, next palindrome is 10...01 with length+1 digits
    if is_all_nines(num):
        return int('1' + ('0' * (length - 1)) + '1')

    # Increment num by 1 since we want strictly larger palindrome
    num += 1
    s = str(num)
    length = len(s)

    half = length // 2
    odd = (length % 2 != 0)

    # Construct palindrome from left half
    if odd:
        left = s[:half]
        mid = s[half]
        right = s[half+1:]
    else:
        left = s[:half]
        mid = ''
        right = s[half:]

    # Form palindrome by mirroring left + mid
    if odd:
        palindrome = left + mid + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) >= num:
        return int(palindrome)

    # If palindrome <= num, need to increment the middle part and mirror again

    if odd:
        # Increment the middle digit and handle carry
        left_mid = left + mid
        incremented = str(int(left_mid) + 1)
        # If increment changes length (e.g. 99 -> 100)
        if len(incremented) > len(left_mid):
            left = incremented[:-1]
            mid = incremented[-1]
        else:
            left = incremented[:-1]
            mid = incremented[-1]
        palindrome = left + mid + left[::-1]
    else:
        # Even length: increment left half and mirror
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            # e.g. 99 -> 100, length increased by 1
            palindrome = incremented + incremented[:-1][::-1]
        else:
            palindrome = incremented + incremented[::-1]

    return int(palindrome)

