def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, s, t = extended_gcd(y, x % y)
        return g, t, s - (x // y) * t

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'

    # scale initial solution
    x0 *= n // g
    y0 *= n // g

    # a/g and b/g for parameter t
    a_div = a // g
    b_div = b // g

    # We want the smallest non-negative x among all solutions:
    # all solutions: x = x0 + t*(b/g)
    # find t so that x >= 0 and x is minimal

    # t_min to make x >= 0:
    # x0 + t*b_div >= 0  =>  t >= -x0/b_div  (consider sign of b_div)
    if b_div == 0:
        # then x = x0 is constant, check if x0 >=0
        if x0 >= 0:
            return (x0, y0)
        else:
            return 'No solution'

    # since t must be integer, compute ceiling or floor depending on sign of b_div
    if b_div > 0:
        t = (-x0 + b_div - 1) // b_div  # ceiling division for positive b_div
    else:
        # b_div < 0
        t = (-x0) // b_div  # floor division for negative b_div (since dividing by negative)

    # now compute x and y for this t
    x = x0 + t * b_div
    y = y0 - t * a_div  # note minus sign because y = y0 - t*(a/g)

    return (x, y)

