def get_total_number_of_sequences(N, K):
    # dp[i][j]: number of sequences of length i ending with value j
    # Values can be from 1 to N
    if K == 0:
        return 0
    # For K=1, any number from 1 to N is a valid sequence
    # We'll use 1-based indexing for convenience

    dp = [ [0]*(N+1) for _ in range(K+1) ]

    # Base case: sequences of length 1
    for val in range(1, N+1):
        dp[1][val] = 1

    for length in range(2, K+1):
        # For each possible end value of the previous sequence,
        # we find all valid next values >= 2 * prev_val
        # To optimize, we can precompute prefix sums
        prefix_sums = [0]*(N+2)
        for x in range(1, N+1):
            prefix_sums[x] = prefix_sums[x-1] + dp[length-1][x]

        for val in range(1, N+1):
            min_prev = (val + 1)//2  # Because prev_val * 2 <= val => prev_val <= val//2
            # Actually, since val >= 2 * prev_val
            # prev_val <= val // 2
            if min_prev > N:
                dp[length][val] = 0
            else:
                dp[length][val] = prefix_sums[min_prev]

    return sum(dp[K][1:])

